                    )}
                    {node.status === 'running' && (
                      <span className="text-[10px] font-mono text-cyan-300 font-bold px-2 py-0.5 rounded bg-cyan-500/20 border border-cyan-500/40 animate-pulse">
                        RUNNING
                      </span>
