                  <div className="w-2 h-2 rounded-full bg-cyan-400 animate-ping" />
                  <span>{scoutStep}</span>
                </div>
              )}
            </form>

            {/* Extracted Scout Dossier */}
            {scoutResult && (
              <motion.div
                initial={{ opacity: 0, y: 15 }}
                animate={{ opacity: 1, y: 0 }}
                className="space-y-5"
