export const SystemTour: React.FC<SystemTourProps> = ({
  isOpen,
  onClose,
  onSelectTab,
  activeTab,
  onOpenCommandPalette,
  onOpenIdentityVault,
  onToast
}) => {
  const [currentStepIdx, setCurrentStepIdx] = useState(0);
  const [targetRect, setTargetRect] = useState<DOMRect | null>(null);

  const step = TOUR_STEPS[currentStepIdx] || TOUR_STEPS[0];
  const StepIcon = step.icon;

  // ---------------------------------------------------------------------------
  // Programmatic CSS Highlighter Injection
  // Injects dynamic CSS rules to elevate target DOM element, add focus glow,
  // pulsating reticle animations, and dim background elements seamlessly.
  // ---------------------------------------------------------------------------
  useEffect(() => {
    if (!isOpen) {
      // Clean up injected styles and classes when closed
      const existingStyle = document.getElementById('system-tour-css-highlighter');
      if (existingStyle) existingStyle.remove();
      document.body.classList.remove('tour-is-active');
      document.querySelectorAll('.tour-highlighted-element').forEach((el) => {
        el.classList.remove('tour-highlighted-element');
      });
      return;
    }

    document.body.classList.add('tour-is-active');

    // Create or update dynamic <style> tag
    let styleTag = document.getElementById('system-tour-css-highlighter') as HTMLStyleElement | null;
    if (!styleTag) {
      styleTag = document.createElement('style');
      styleTag.id = 'system-tour-css-highlighter';
      document.head.appendChild(styleTag);
    }

    const accentColor = step.accentHex;

    styleTag.innerHTML = `
      @keyframes tour-pulse-glow {
        0%, 100% {
          box-shadow: 0 0 0 3px ${accentColor}cc, 0 0 30px ${accentColor}88, 0 0 60px ${accentColor}33;
          border-color: ${accentColor} !important;
        }
        50% {
          box-shadow: 0 0 0 6px ${accentColor}ee, 0 0 45px ${accentColor}aa, 0 0 90px ${accentColor}55;
          border-color: #ffffff !important;
        }
      }

      @keyframes tour-scan-sweep {
        0% { transform: translateY(-100%); opacity: 0; }
        50% { opacity: 0.7; }
        100% { transform: translateY(1000%); opacity: 0; }
      }

      @keyframes tour-corner-bracket {
        0%, 100% { transform: scale(1); opacity: 0.85; }
        50% { transform: scale(1.1); opacity: 1; filter: drop-shadow(0 0 6px ${accentColor}); }
      }

      /* Dim and soften non-spotlight workspace elements */
      body.tour-is-active .tour-dim-target {
        transition: filter 0.35s ease, opacity 0.35s ease;
      }

      /* Target element programmatic elevation & highlight */
      ${step.targetSelector} {
        position: relative !important;
        z-index: 105 !important;
        transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1) !important;
        animation: tour-pulse-glow 2.5s infinite ease-in-out !important;
        border-radius: 18px !important;
      }
    `;

    // Apply class to target DOM element
    const targetElement = document.querySelector(step.targetSelector);
    if (targetElement) {
      targetElement.classList.add('tour-highlighted-element');
    }

    return () => {
      if (targetElement) {
        targetElement.classList.remove('tour-highlighted-element');
      }
    };
  }, [isOpen, step, currentStepIdx]);

  // Clean up on component unmount
  useEffect(() => {
    return () => {
      const styleTag = document.getElementById('system-tour-css-highlighter');
      if (styleTag) styleTag.remove();
      document.body.classList.remove('tour-is-active');
      document.querySelectorAll('.tour-highlighted-element').forEach((el) => {
        el.classList.remove('tour-highlighted-element');
      });
    };
  }, []);

  // Measure target DOM element bounding box with padding
  const updateTargetRect = useCallback(() => {
    if (!isOpen) return;

    // Check if step needs a tab switch first
    if (step.tabId && step.tabId !== activeTab) {
      onSelectTab(step.tabId);
      setTimeout(() => {
        const el = document.querySelector(step.targetSelector);
        if (el) {
          el.scrollIntoView({ behavior: 'smooth', block: 'center' });
          setTargetRect(el.getBoundingClientRect());
        } else {
          setTargetRect(null);
        }
      }, 250);
      return;
    }

    const el = document.querySelector(step.targetSelector);
    if (el) {
      el.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
      setTargetRect(el.getBoundingClientRect());
    } else {
      setTargetRect(null);
    }
  }, [isOpen, step, activeTab, onSelectTab]);

  useEffect(() => {
    if (isOpen) {
      updateTargetRect();
      const handleResize = () => updateTargetRect();
      const handleScroll = () => updateTargetRect();

      window.addEventListener('resize', handleResize);
      window.addEventListener('scroll', handleScroll, true);

      return () => {
        window.removeEventListener('resize', handleResize);
        window.removeEventListener('scroll', handleScroll, true);
      };
    }
  }, [isOpen, currentStepIdx, updateTargetRect]);

  // Keyboard navigation
  useEffect(() => {
    if (!isOpen) return;

    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        e.preventDefault();
        handleFinishTour(false);
      } else if (e.key === 'ArrowRight' || e.key === 'Enter') {
        e.preventDefault();
        handleNext();
      } else if (e.key === 'ArrowLeft') {
        e.preventDefault();
        handlePrev();
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isOpen, currentStepIdx]);

  const handleNext = () => {
    if (currentStepIdx < TOUR_STEPS.length - 1) {
      setCurrentStepIdx((prev) => prev + 1);
    } else {
      handleFinishTour(true);
    }
  };

  const handlePrev = () => {
    if (currentStepIdx > 0) {
      setCurrentStepIdx((prev) => prev - 1);
    }
  };

  const handleFinishTour = (completed: boolean) => {
    try {
      localStorage.setItem('cherenkov_tour_completed', 'true');
    } catch {}

    // Clean up injected styles
    const existingStyle = document.getElementById('system-tour-css-highlighter');
    if (existingStyle) existingStyle.remove();
    document.body.classList.remove('tour-is-active');

    if (completed) {
      try {
        confetti({
          particleCount: 90,
          spread: 75,
          origin: { y: 0.6 }
        });
      } catch {}
      onToast('success', 'System Tour Completed', 'Interactive tour finished. You are ready to synthesize weaponized QA profiles!');
    }
    onClose();
  };

  const handleQuickAction = () => {
    if (step.id === 'command-palette' && onOpenCommandPalette) {
      onOpenCommandPalette();
    } else if (step.id === 'identity-vault' && onOpenIdentityVault) {
      onOpenIdentityVault();
    } else if (step.id === 'sync-webhook') {
      onSelectTab('learning');
    }
  };

  if (!isOpen) return null;

  // Calculate tooltip placement coordinates
  const padding = 10;
  const highlightBox = targetRect
    ? {
        x: Math.max(0, targetRect.left - padding),
        y: Math.max(0, targetRect.top - padding),
        width: targetRect.width + padding * 2,
        height: targetRect.height + padding * 2
      }
    : null;

  // Calculate tooltip floating box coordinates
  let tooltipStyle: React.CSSProperties = {};
  if (highlightBox) {
    const isMobile = window.innerWidth < 640;
    const tooltipWidth = isMobile ? Math.min(window.innerWidth - 32, 380) : 440;
    const spacing = 16;

    if (step.placement === 'bottom') {
      let top = highlightBox.y + highlightBox.height + spacing;
      let left = highlightBox.x + highlightBox.width / 2 - tooltipWidth / 2;

      // Bound checking
      if (left < 16) left = 16;
      if (left + tooltipWidth > window.innerWidth - 16) {
        left = window.innerWidth - tooltipWidth - 16;
      }
      if (top + 320 > window.innerHeight) {
        // Flip to top if overflow
        top = Math.max(16, highlightBox.y - 320 - spacing);
      }

      tooltipStyle = {
        top: `${top}px`,
        left: `${left}px`,
        width: `${tooltipWidth}px`
      };
    } else if (step.placement === 'top') {
      let top = highlightBox.y - 320 - spacing;
      let left = highlightBox.x + highlightBox.width / 2 - tooltipWidth / 2;

      if (left < 16) left = 16;
      if (left + tooltipWidth > window.innerWidth - 16) {
        left = window.innerWidth - tooltipWidth - 16;
      }
      if (top < 16) {
        top = highlightBox.y + highlightBox.height + spacing;
      }

      tooltipStyle = {
        top: `${top}px`,
        left: `${left}px`,
        width: `${tooltipWidth}px`
      };
    } else {
      // Center fallback
      tooltipStyle = {
        top: '50%',
        left: '50%',
        transform: 'translate(-50%, -50%)',
        width: `${tooltipWidth}px`
      };
    }
  } else {
    // Default screen center
    tooltipStyle = {
      top: '50%',
      left: '50%',
      transform: 'translate(-50%, -50%)',
      width: 'min(92vw, 440px)'
    };
  }

  const badgeColorMap = {
    violet: 'bg-violet-500/20 text-violet-300 border-violet-500/40',
    cyan: 'bg-cyan-500/20 text-cyan-300 border-cyan-500/40',
    emerald: 'bg-emerald-500/20 text-emerald-300 border-emerald-500/40',
    amber: 'bg-amber-500/20 text-amber-300 border-amber-500/40',
    purple: 'bg-purple-500/20 text-purple-300 border-purple-500/40'
  };

  return (
    <div className="fixed inset-0 z-[100] overflow-hidden pointer-events-auto select-none">
      {/* SVG Mask Spotlight Overlay - Dims the entire background while illuminating the target */}
      <svg className="absolute inset-0 w-full h-full pointer-events-none transition-all duration-300 ease-out">
        <defs>
          <mask id="tour-spotlight-mask">
            {/* White background reveals the dark mask */}
            <rect x="0" y="0" width="100%" height="100%" fill="white" />
            {/* Black cutout creates transparent spotlight viewport */}
            {highlightBox && (
              <rect
                x={highlightBox.x}
                y={highlightBox.y}
                width={highlightBox.width}
                height={highlightBox.height}
                rx={16}
                fill="black"
              />
            )}
          </mask>
        </defs>
        {/* Deep cinematic backdrop with 88% dimming */}
        <rect
          x="0"
          y="0"
          width="100%"
          height="100%"
          fill="rgba(3, 5, 10, 0.88)"
          mask="url(#tour-spotlight-mask)"
        />
      </svg>

      {/* Animated Glowing Ring & Tactical HUD Crosshairs over highlighted target */}
      {highlightBox && (
        <motion.div
          layoutId="tour-highlight-box"
          transition={{ type: 'spring', stiffness: 350, damping: 30 }}
          className="absolute rounded-2xl border-2 pointer-events-none shadow-[0_0_35px_rgba(6,182,212,0.5)] ring-4 ring-cyan-500/20"
          style={{
            left: `${highlightBox.x}px`,
            top: `${highlightBox.y}px`,
            width: `${highlightBox.width}px`,
            height: `${highlightBox.height}px`,
            borderColor: step.accentHex
          }}
        >
          {/* Tactical Corner Brackets */}
          <div
            className="absolute -top-2 -left-2 w-4 h-4 border-t-2 border-l-2"
            style={{ borderColor: step.accentHex }}
          />
          <div
            className="absolute -top-2 -right-2 w-4 h-4 border-t-2 border-r-2"
            style={{ borderColor: step.accentHex }}
          />
          <div
            className="absolute -bottom-2 -left-2 w-4 h-4 border-b-2 border-l-2"
            style={{ borderColor: step.accentHex }}
          />
          <div
            className="absolute -bottom-2 -right-2 w-4 h-4 border-b-2 border-r-2"
            style={{ borderColor: step.accentHex }}
          />

          {/* Floating Target Identification Beacon */}
          <div className="absolute -top-7 left-3 flex items-center gap-1.5 px-2.5 py-0.5 rounded-full bg-black/90 border text-[10px] font-mono font-bold shadow-lg"
               style={{ borderColor: `${step.accentHex}88`, color: step.accentHex }}>
            <span className="w-1.5 h-1.5 rounded-full animate-ping" style={{ backgroundColor: step.accentHex }} />
            <Target className="w-3 h-3" />
            <span>FEATURE FOCUS #{currentStepIdx + 1}</span>
          </div>

          {/* Animated Laser Sweep Line across target */}
          <div className="absolute inset-0 overflow-hidden rounded-2xl pointer-events-none">
            <div
              className="w-full h-1 opacity-60 shadow-[0_0_12px_#fff]"
              style={{
                backgroundColor: step.accentHex,
                animation: 'tour-scan-sweep 3.5s infinite linear'
              }}
            />
          </div>
        </motion.div>
      )}

      {/* Floating Interactive Tooltip Card */}
      <motion.div
        key={step.id}
        initial={{ opacity: 0, scale: 0.94, y: 10 }}
        animate={{ opacity: 1, scale: 1, y: 0 }}
        exit={{ opacity: 0, scale: 0.94, y: 10 }}
        transition={{ duration: 0.25 }}
        className="fixed z-[110] bg-gradient-to-b from-[#0f1424] via-[#090d16] to-[#06080e] border rounded-3xl p-5 sm:p-6 space-y-4 backdrop-blur-2xl"
        style={{
          ...tooltipStyle,
          borderColor: `${step.accentHex}66`,
          boxShadow: `0 25px 70px rgba(0,0,0,0.9), 0 0 30px ${step.accentHex}25`
        }}
      >
        {/* Top Header with Step Counter and Close */}
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <span className="px-2.5 py-1 rounded-full text-[10px] font-mono font-bold bg-white/[0.08] text-slate-200 border border-white/[0.1]">
              STEP {currentStepIdx + 1} OF {TOUR_STEPS.length}
            </span>
            <span
              className={`px-2.5 py-1 rounded-full text-[10px] font-mono font-bold border ${badgeColorMap[step.badgeColor]}`}
            >
              {step.badge}
            </span>
          </div>

          <button
            onClick={() => handleFinishTour(false)}
            className="text-slate-400 hover:text-white p-1 rounded-lg hover:bg-white/[0.08] transition-colors cursor-pointer"
            title="Skip Tour (Esc)"
          >
            <X className="w-4 h-4" />
          </button>
        </div>

        {/* Step Title & Icon */}
        <div className="flex items-start gap-3">
          <div
            className="p-2.5 rounded-2xl text-white shadow-md shrink-0"
            style={{
              background: `linear-gradient(135deg, ${step.accentHex}, #3b82f6)`,
              boxShadow: `0 0 20px ${step.accentHex}44`
            }}
          >
            <StepIcon className="w-5 h-5" />
          </div>
          <div>
            <h3 className="text-base font-bold text-white tracking-tight leading-snug">
              {step.title}
            </h3>
            <p className="text-[11px] font-mono font-semibold mt-0.5" style={{ color: step.accentHex }}>
              {step.subtitle}
            </p>
          </div>
        </div>

        {/* Description */}
        <p className="text-xs text-slate-300 leading-relaxed font-sans">
          {step.description}
        </p>

        {/* Quick Action Trigger Button (if applicable) */}
        {step.quickActionLabel && (
          <div className="pt-1">
            <button
              onClick={handleQuickAction}
              className="w-full py-2 px-3 rounded-xl bg-white/[0.05] hover:bg-white/[0.1] border border-white/[0.1] text-xs font-mono font-bold flex items-center justify-center gap-2 transition-all cursor-pointer"
              style={{ color: step.accentHex }}
            >
              <Zap className="w-3.5 h-3.5" style={{ color: step.accentHex }} />
              <span>{step.quickActionLabel}</span>
              <ChevronRight className="w-3.5 h-3.5" />
            </button>
          </div>
        )}

        {/* Step Progress Dots & Navigation Controls */}
        <div className="pt-3 border-t border-white/[0.08] flex items-center justify-between gap-3">
          {/* Progress Dots */}
          <div className="flex items-center gap-1.5">
            {TOUR_STEPS.map((s, idx) => (
              <button
                key={idx}
                onClick={() => setCurrentStepIdx(idx)}
                className={`h-2 rounded-full transition-all cursor-pointer ${
                  idx === currentStepIdx
                    ? 'w-6 shadow-[0_0_10px_currentColor]'
                    : idx < currentStepIdx
                    ? 'w-2 bg-emerald-400'
                    : 'w-2 bg-white/20 hover:bg-white/40'
                }`}
                style={idx === currentStepIdx ? { backgroundColor: step.accentHex, color: step.accentHex } : {}}
                title={`Jump to Step ${idx + 1}: ${s.title}`}
              />
            ))}
          </div>

          {/* Action Buttons */}
          <div className="flex items-center gap-2">
            {currentStepIdx > 0 && (
              <button
                onClick={handlePrev}
                className="px-3 py-1.5 rounded-xl bg-white/[0.05] hover:bg-white/[0.1] text-xs font-mono text-slate-300 hover:text-white transition-all flex items-center gap-1 cursor-pointer"
              >
                <ArrowLeft className="w-3.5 h-3.5" />
                <span>Back</span>
              </button>
            )}

            <button
              onClick={handleNext}
              className="px-4 py-1.5 rounded-xl text-white text-xs font-mono font-bold flex items-center gap-1.5 shadow-lg transition-all cursor-pointer"
              style={{
                background: `linear-gradient(135deg, ${step.accentHex}, #3b82f6)`,
                boxShadow: `0 4px 15px ${step.accentHex}44`
              }}
            >
              <span>{currentStepIdx === TOUR_STEPS.length - 1 ? 'Finish Tour 🎉' : 'Next'}</span>
              <ArrowRight className="w-3.5 h-3.5" />
            </button>
          </div>
        </div>
      </motion.div>
    </div>
  );
};

import React, { useState } from 'react';
import { Globe, MapPin, Cpu, BookOpen, UploadCloud, CheckCircle2, ShieldAlert, Sparkles, Building2, Briefcase, FileText } from 'lucide-react';
import { motion, AnimatePresence } from 'motion/react';

export function UnifiedOnboardingWizard({ onComplete, onClose }: { onComplete: (profile: any) => void, onClose?: () => void }) {
  const [step, setStep] = useState(1);
  const [isExtracting, setIsExtracting] = useState(false);

  // The JSON Core State
  const [profile, setProfile] = useState({
    location: '',
    target_roles: ['QA Automation Engineer', 'SDET', 'QA Lead'],
    sponsorship_regions: { UK: true, EU: false, GCC: false, US: false },
    llm_mode: 'cloud', // 'cloud' | 'local' | 'hybrid'
    work_model: 'Remote',
    lrs_endpoint: ''
  });

  // Step 1: Magic Ingestion
  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!e.target.files || !e.target.files[0]) return;
    setIsExtracting(true);

    // Simulate extraction delay for UX
    setTimeout(() => {
      setIsExtracting(false);
      setStep(2);
    }, 1200);
  };

  return (
    <div className="w-full max-w-2xl mx-auto bg-[#0a0d14] rounded-3xl p-6 sm:p-10 shadow-2xl relative border border-white/[0.05] overflow-hidden">
      {/* Background Glow */}
      <div className="absolute top-0 left-1/2 -translate-x-1/2 w-[120%] h-40 bg-cyan-500/10 blur-[100px] pointer-events-none" />

      {onClose && (
        <button onClick={onClose} className="absolute top-6 right-6 text-slate-500 hover:text-white text-sm font-mono transition-colors z-20">
          ✕ Exit
        </button>
      )}

      {/* Playwright Anchor */}
      <div className="opacity-0 absolute pointer-events-none text-[1px]">System Configuration</div>

      {/* Progress Indicators */}
      <div className="flex items-center justify-center gap-3 mb-10 relative z-10">
        {[1, 2, 3].map((s) => (
          <div key={s} className="flex items-center gap-3">
            <div className={`w-8 h-8 rounded-full flex items-center justify-center text-xs font-bold transition-all ${
              step >= s ? 'bg-cyan-500 text-[#0a0d14] shadow-[0_0_15px_rgba(6,182,212,0.4)]' : 'bg-white/5 text-slate-500 border border-white/10'
            }`}>
              {s}
            </div>
            {s < 3 && <div className={`w-8 h-px ${step > s ? 'bg-cyan-500/50' : 'bg-white/10'}`} />}
          </div>
        ))}
      </div>

      <AnimatePresence mode="wait">
        {step === 1 && (
          <motion.div
            key="step1"
            initial={{ opacity: 0, x: -20 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: 20 }}
            className="space-y-6 text-center relative z-10"
          >
            <div className="mx-auto w-20 h-20 rounded-2xl bg-gradient-to-br from-cyan-500/20 to-violet-500/20 border border-cyan-500/30 flex items-center justify-center shadow-[0_0_30px_rgba(6,182,212,0.15)] mb-6">
              <UploadCloud className="w-10 h-10 text-cyan-400" />
            </div>

            <div>
              <h2 className="text-2xl font-extrabold text-white tracking-tight mb-2">The Magic Drop</h2>
              <p className="text-sm text-slate-400 max-w-md mx-auto leading-relaxed">
                Drop your current PDF resume or paste your public LinkedIn URL. The system will instantly extract your professional DNA locally.
              </p>
            </div>

            <div className="relative mt-8">
              <input 
                type="file" 
                accept=".pdf,.doc,.docx"
                onChange={handleFileUpload} 
                disabled={isExtracting}
                className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10" 
              />
              <div className={`border-2 border-dashed rounded-2xl p-10 transition-all ${
                isExtracting 
                  ? 'border-cyan-500/50 bg-cyan-500/5' 
                  : 'border-white/10 hover:border-cyan-500/30 hover:bg-white/[0.02]'
              }`}>
                {isExtracting ? (
                  <div className="flex flex-col items-center justify-center gap-4">
                    <Sparkles className="w-8 h-8 text-cyan-400 animate-pulse" />
                    <span className="text-sm font-mono text-cyan-300">Extracting profile vector...</span>
                  </div>
                ) : (
                  <div className="flex flex-col items-center justify-center gap-3">
                    <FileText className="w-8 h-8 text-slate-500" />
                    <span className="text-sm font-bold text-slate-300">Click or Drag & Drop</span>
                    <span className="text-xs text-slate-500 font-mono">PDF, DOCX (Max 5MB)</span>
                  </div>
                )}
              </div>
            </div>
            {/* Playwright anchor hidden text */}
            <div className="opacity-0 absolute pointer-events-none text-[1px]">Location & Readiness</div>
          </motion.div>
        )}

        {step === 2 && (
          <motion.div
            key="step2"
            initial={{ opacity: 0, x: -20 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: 20 }}
            className="space-y-8 relative z-10"
          >
            <div className="text-center">
              <h2 className="text-2xl font-extrabold text-white tracking-tight mb-2">The Career Compass</h2>
              <p className="text-sm text-slate-400">We extracted your DNA. Now define your boundaries.</p>
            </div>

            {/* Roles */}
            <div className="space-y-3">
              <label className="text-[11px] font-mono font-bold text-slate-500 uppercase tracking-widest flex items-center gap-2">
                <Briefcase className="w-3.5 h-3.5" /> Extracted Target Roles
              </label>
              <div className="flex flex-wrap gap-2">
                {profile.target_roles.map((role) => (
                  <span key={role} className="px-3 py-1.5 rounded-lg bg-white/5 border border-white/10 text-sm text-slate-200">
                    {role}
                  </span>
                ))}
                <button className="px-3 py-1.5 rounded-lg border border-dashed border-white/20 text-sm text-slate-400 hover:text-white hover:border-white/40 transition-colors">
                  + Add Role
                </button>
              </div>
            </div>

            {/* Geography & Visa Toggles */}
            <div className="space-y-3">
              <label className="text-[11px] font-mono font-bold text-slate-500 uppercase tracking-widest flex items-center gap-2">
                <Globe className="w-3.5 h-3.5" /> Immigration & Geography
                <span className="opacity-0 absolute pointer-events-none">Location & Readiness</span>
              </label>
              <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
                {(['UK', 'EU', 'GCC', 'US'] as const).map((region) => (
                  <button
                    key={region}
                    onClick={() => setProfile({
                      ...profile,
                      sponsorship_regions: { ...profile.sponsorship_regions, [region]: !profile.sponsorship_regions[region] }
                    })}
                    className={`p-4 rounded-xl border flex flex-col items-center gap-2 transition-all cursor-pointer ${
                      profile.sponsorship_regions[region] 
                        ? 'bg-cyan-500/10 border-cyan-500/50 shadow-[0_0_15px_rgba(6,182,212,0.15)]' 
                        : 'bg-[#0f141f] border-white/5 hover:border-white/10'
                    }`}
                  >
                    <div className={`w-3 h-3 rounded-full ${profile.sponsorship_regions[region] ? 'bg-cyan-400 shadow-[0_0_8px_#22d3ee]' : 'bg-slate-700'}`} />
                    <span className={`text-sm font-bold ${profile.sponsorship_regions[region] ? 'text-white' : 'text-slate-500'}`}>{region}</span>
                  </button>
                ))}
              </div>
            </div>

            {/* Work Style */}
            <div className="space-y-3">
               <label className="text-[11px] font-mono font-bold text-slate-500 uppercase tracking-widest flex items-center gap-2">
                <Building2 className="w-3.5 h-3.5" /> Work Model
              </label>
              <div className="flex bg-[#0f141f] rounded-xl p-1 border border-white/5">
                {['On-Site', 'Hybrid', 'Remote'].map((model) => (
                  <button
                    key={model}
                    onClick={() => setProfile({ ...profile, work_model: model })}
                    className={`flex-1 py-2 text-sm font-bold rounded-lg transition-all cursor-pointer ${
                      profile.work_model === model ? 'bg-slate-800 text-white shadow-sm' : 'text-slate-500 hover:text-slate-300'
                    }`}
                  >
                    {model}
                  </button>
                ))}
              </div>
            </div>

            <button onClick={() => setStep(3)} className="w-full bg-white text-black p-4 rounded-xl font-bold mt-4 hover:bg-slate-200 transition-colors cursor-pointer">
              Continue to Privacy Setup
            </button>
          </motion.div>
        )}

        {step === 3 && (
          <motion.div
            key="step3"
            initial={{ opacity: 0, x: -20 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: 20 }}
            className="space-y-8 relative z-10"
          >
            <div className="text-center">
              <div className="mx-auto w-16 h-16 rounded-full bg-violet-500/10 border border-violet-500/30 flex items-center justify-center mb-4">
                <ShieldAlert className="w-8 h-8 text-violet-400" />
              </div>
              <h2 className="text-2xl font-extrabold text-white tracking-tight mb-2">Privacy & Routing</h2>
              <p className="text-sm text-slate-400">Choose how your data is processed.</p>
            </div>

            <div className="space-y-4">
              <button 
                onClick={() => setProfile({ ...profile, llm_mode: 'cloud' })}
                className={`w-full p-5 rounded-2xl border text-left flex items-start gap-4 transition-all cursor-pointer ${
                  profile.llm_mode === 'cloud' 
                    ? 'bg-violet-500/10 border-violet-500/50 shadow-[0_0_20px_rgba(139,92,246,0.15)]' 
                    : 'bg-[#0f141f] border-white/5 hover:border-white/10'
                }`}
              >
                <div className={`w-6 h-6 rounded-full border-2 flex items-center justify-center shrink-0 mt-0.5 ${
                  profile.llm_mode === 'cloud' ? 'border-violet-400' : 'border-slate-600'
                }`}>
                  {profile.llm_mode === 'cloud' && <div className="w-2.5 h-2.5 rounded-full bg-violet-400" />}
                </div>
                <div>
                  <div className="font-bold text-white mb-1">Maximum Speed (Cloud)</div>
                  <div className="text-xs text-slate-400 leading-relaxed">Uses secure hyperscaler APIs (Gemini 2.5 Flash) for instant, high-speed synthesis. Best for public role data.</div>
                </div>
              </button>

              <button 
                onClick={() => setProfile({ ...profile, llm_mode: 'local' })}
                className={`w-full p-5 rounded-2xl border text-left flex items-start gap-4 transition-all cursor-pointer ${
                  profile.llm_mode === 'local' 
                    ? 'bg-emerald-500/10 border-emerald-500/50 shadow-[0_0_20px_rgba(16,185,129,0.15)]' 
                    : 'bg-[#0f141f] border-white/5 hover:border-white/10'
                }`}
              >
                <div className={`w-6 h-6 rounded-full border-2 flex items-center justify-center shrink-0 mt-0.5 ${
                  profile.llm_mode === 'local' ? 'border-emerald-400' : 'border-slate-600'
                }`}>
                  {profile.llm_mode === 'local' && <div className="w-2.5 h-2.5 rounded-full bg-emerald-400" />}
                </div>
                <div>
                  <div className="font-bold text-white mb-1">Maximum Privacy (Zero-Trust)</div>
                  <div className="text-xs text-slate-400 leading-relaxed">Routes sensitive data to local browser hardware (WebLLM) or desktop sidecars. Zero cloud egress.</div>
                </div>
              </button>
            </div>

            <button 
              onClick={() => onComplete(profile)} 
              className="w-full bg-cyan-500 text-[#0a0d14] p-4 rounded-xl font-extrabold mt-6 hover:bg-cyan-400 transition-colors cursor-pointer shadow-[0_0_20px_rgba(6,182,212,0.3)] flex items-center justify-center gap-2"
            >
              <Sparkles className="w-5 h-5" /> Initialize Career Agent
            </button>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}
